create extension if not exists pgcrypto with schema extensions;

-- -----------------------------------------------------------------------------
-- Enums
-- -----------------------------------------------------------------------------
do $$ begin
  create type public.publish_status as enum ('draft', 'published');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.message_status as enum ('new', 'read', 'archived');
exception when duplicate_object then null; end $$;

-- -----------------------------------------------------------------------------
-- Helpers
-- -----------------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- Administrators
-- Rows are created only with the service role (see scripts/create-admin.mjs).
-- There is no public sign-up path to this table.
-- -----------------------------------------------------------------------------
create table if not exists public.admin_users (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  created_at timestamptz not null default now()
);

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.admin_users where user_id = (select auth.uid())
  );
$$;

revoke all on function public.is_admin() from public;
grant execute on function public.is_admin() to anon, authenticated;

-- -----------------------------------------------------------------------------
-- Singletons: profile and site settings (exactly one row each, id = 1)
-- -----------------------------------------------------------------------------
create table if not exists public.profiles (
  id               smallint primary key default 1 check (id = 1),
  full_name        text not null check (char_length(full_name) between 1 and 120),
  headline         text not null default '' check (char_length(headline) <= 160),
  short_intro      text not null default '' check (char_length(short_intro) <= 600),
  bio              text not null default '' check (char_length(bio) <= 6000),
  story            text not null default '' check (char_length(story) <= 10000),
  background       text not null default '' check (char_length(background) <= 6000),
  learning_journey text not null default '' check (char_length(learning_journey) <= 6000),
  goals            text not null default '' check (char_length(goals) <= 4000),
  interests        text[] not null default '{}',
  location         text not null default '' check (char_length(location) <= 160),
  availability     text not null default '' check (char_length(availability) <= 160),
  avatar_url       text,
  avatar_alt       text not null default '' check (char_length(avatar_alt) <= 300),
  resume_url       text,
  updated_at       timestamptz not null default now()
);

create table if not exists public.site_settings (
  id                  smallint primary key default 1 check (id = 1),
  site_name           text not null default 'Shahruz Ziyodullayev' check (char_length(site_name) between 1 and 120),
  logo_url            text,
  favicon_url         text,
  accent_color        text not null default '#10b981' check (accent_color ~* '^#[0-9a-f]{6}$'),
  enable_3d           boolean not null default true,
  enable_particles    boolean not null default true,
  hero_eyebrow        text not null default '' check (char_length(hero_eyebrow) <= 120),
  hero_title          text not null default '' check (char_length(hero_title) <= 200),
  hero_description    text not null default '' check (char_length(hero_description) <= 800),
  cta_primary_label   text not null default 'Loyihalarimni ko’rish' check (char_length(cta_primary_label) <= 60),
  cta_secondary_label text not null default 'Men bilan bog’lanish' check (char_length(cta_secondary_label) <= 60),
  seo_title           text not null default '' check (char_length(seo_title) <= 120),
  seo_description     text not null default '' check (char_length(seo_description) <= 320),
  seo_keywords        text[] not null default '{}',
  og_image_url        text,
  site_url            text,
  contact_email       text check (contact_email is null or contact_email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  contact_phone       text check (char_length(contact_phone) <= 40),
  contact_location    text check (char_length(contact_location) <= 160),
  contact_note        text not null default '' check (char_length(contact_note) <= 600),
  show_resume         boolean not null default true,
  footer_text         text not null default '' check (char_length(footer_text) <= 400),
  nav_items           jsonb not null default '[]'::jsonb check (jsonb_typeof(nav_items) = 'array'),
  footer_links        jsonb not null default '[]'::jsonb check (jsonb_typeof(footer_links) = 'array'),
  privacy_policy      text not null default '' check (char_length(privacy_policy) <= 30000),
  updated_at          timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- Content collections
-- -----------------------------------------------------------------------------
create table if not exists public.projects (
  id              uuid primary key default gen_random_uuid(),
  slug            text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) <= 120),
  title           text not null check (char_length(title) between 1 and 160),
  summary         text not null default '' check (char_length(summary) <= 400),
  description     text not null default '' check (char_length(description) <= 20000),
  role            text not null default '' check (char_length(role) <= 160),
  category        text not null default '' check (char_length(category) <= 80),
  tags            text[] not null default '{}',
  technologies    text[] not null default '{}',
  thumbnail_url   text,
  thumbnail_alt   text not null default '' check (char_length(thumbnail_alt) <= 300),
  gallery         jsonb not null default '[]'::jsonb check (jsonb_typeof(gallery) = 'array'),
  live_url        text,
  source_url      text,
  started_on      date,
  completed_on    date,
  featured        boolean not null default false,
  status          public.publish_status not null default 'draft',
  sort_order      integer not null default 0,
  published_at    timestamptz,
  seo_title       text not null default '' check (char_length(seo_title) <= 120),
  seo_description text not null default '' check (char_length(seo_description) <= 320),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint projects_dates_chk check (completed_on is null or started_on is null or completed_on >= started_on)
);

create table if not exists public.achievements (
  id              uuid primary key default gen_random_uuid(),
  title           text not null check (char_length(title) between 1 and 200),
  description     text not null default '' check (char_length(description) <= 6000),
  kind            text not null default 'award'
                  check (kind in ('award', 'competition', 'certificate', 'milestone', 'other')),
  category        text not null default '' check (char_length(category) <= 80),
  organization    text not null default '' check (char_length(organization) <= 200),
  achieved_on     date,
  image_url       text,
  image_alt       text not null default '' check (char_length(image_alt) <= 300),
  certificate_url text,
  credential_url  text,
  featured        boolean not null default false,
  status          public.publish_status not null default 'draft',
  sort_order      integer not null default 0,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

create table if not exists public.skills (
  id          uuid primary key default gen_random_uuid(),
  name        text not null check (char_length(name) between 1 and 80),
  category    text not null default '' check (char_length(category) <= 80),
  -- Optional; only shown when the administrator explicitly enters a value.
  level       smallint check (level is null or level between 0 and 100),
  level_label text not null default '' check (char_length(level_label) <= 40),
  description text not null default '' check (char_length(description) <= 600),
  featured    boolean not null default false,
  status      public.publish_status not null default 'draft',
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create table if not exists public.education (
  id          uuid primary key default gen_random_uuid(),
  institution text not null check (char_length(institution) between 1 and 200),
  program     text not null default '' check (char_length(program) <= 200),
  field       text not null default '' check (char_length(field) <= 200),
  location    text not null default '' check (char_length(location) <= 160),
  start_date  date,
  end_date    date,
  is_current  boolean not null default false,
  description text not null default '' check (char_length(description) <= 6000),
  image_url   text,
  url         text,
  status      public.publish_status not null default 'draft',
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint education_dates_chk check (end_date is null or start_date is null or end_date >= start_date)
);

create table if not exists public.experience (
  id              uuid primary key default gen_random_uuid(),
  organization    text not null check (char_length(organization) between 1 and 200),
  role            text not null default '' check (char_length(role) <= 200),
  employment_type text not null default '' check (char_length(employment_type) <= 80),
  location        text not null default '' check (char_length(location) <= 160),
  start_date      date,
  end_date        date,
  is_current      boolean not null default false,
  description     text not null default '' check (char_length(description) <= 6000),
  highlights      text[] not null default '{}',
  image_url       text,
  url             text,
  status          public.publish_status not null default 'draft',
  sort_order      integer not null default 0,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint experience_dates_chk check (end_date is null or start_date is null or end_date >= start_date)
);

-- Every uploaded file. Images flagged `in_gallery` + published appear on /gallery.
create table if not exists public.media (
  id          uuid primary key default gen_random_uuid(),
  bucket      text not null default 'media' check (bucket = 'media'),
  path        text not null unique check (char_length(path) between 1 and 400),
  url         text not null,
  file_name   text not null check (char_length(file_name) between 1 and 255),
  mime_type   text not null check (char_length(mime_type) <= 120),
  size_bytes  bigint not null check (size_bytes >= 0),
  kind        text not null check (kind in ('image', 'document')),
  width       integer check (width is null or width > 0),
  height      integer check (height is null or height > 0),
  alt_text    text not null default '' check (char_length(alt_text) <= 300),
  caption     text not null default '' check (char_length(caption) <= 600),
  category    text not null default '' check (char_length(category) <= 80),
  in_gallery  boolean not null default false,
  status      public.publish_status not null default 'draft',
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create table if not exists public.social_links (
  id         uuid primary key default gen_random_uuid(),
  platform   text not null check (char_length(platform) between 1 and 40),
  label      text not null default '' check (char_length(label) <= 80),
  url        text not null check (url ~* '^(https?://|mailto:|tel:)'),
  status     public.publish_status not null default 'draft',
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.stats (
  id          uuid primary key default gen_random_uuid(),
  label       text not null check (char_length(label) between 1 and 80),
  value       text not null check (char_length(value) between 1 and 24),
  description text not null default '' check (char_length(description) <= 200),
  status      public.publish_status not null default 'draft',
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create table if not exists public.contact_messages (
  id         uuid primary key default gen_random_uuid(),
  name       text not null check (char_length(name) between 2 and 120),
  email      text not null check (char_length(email) <= 254 and email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  subject    text not null default '' check (char_length(subject) <= 200),
  message    text not null check (char_length(message) between 10 and 5000),
  status     public.message_status not null default 'new',
  ip_hash    text check (char_length(ip_hash) <= 128),
  user_agent text check (char_length(user_agent) <= 400),
  created_at timestamptz not null default now()
);

create table if not exists public.activity_log (
  id         bigint generated always as identity primary key,
  entity     text not null,
  entity_id  text,
  action     text not null check (action in ('create', 'update', 'delete')),
  title      text,
  actor      uuid,
  created_at timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- Indexes
-- -----------------------------------------------------------------------------
create index if not exists projects_public_idx      on public.projects (status, featured desc, sort_order, created_at desc);
create index if not exists projects_tags_idx        on public.projects using gin (tags);
create index if not exists projects_tech_idx        on public.projects using gin (technologies);
create index if not exists achievements_public_idx  on public.achievements (status, achieved_on desc nulls last, sort_order);
create index if not exists skills_public_idx        on public.skills (status, category, sort_order);
create index if not exists education_public_idx     on public.education (status, sort_order, start_date desc);
create index if not exists experience_public_idx    on public.experience (status, sort_order, start_date desc);
create index if not exists media_gallery_idx        on public.media (in_gallery, status, sort_order) where kind = 'image';
create index if not exists media_created_idx        on public.media (created_at desc);
create index if not exists social_links_public_idx  on public.social_links (status, sort_order);
create index if not exists stats_public_idx         on public.stats (status, sort_order);
create index if not exists contact_created_idx      on public.contact_messages (created_at desc);
create index if not exists contact_ip_idx           on public.contact_messages (ip_hash, created_at desc);
create index if not exists activity_created_idx     on public.activity_log (created_at desc);

-- -----------------------------------------------------------------------------
-- Triggers: updated_at, published_at, activity log
-- -----------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['profiles','site_settings','projects','achievements','skills',
                           'education','experience','media','social_links','stats']
  loop
    execute format('drop trigger if exists set_updated_at on public.%I', t);
    execute format('create trigger set_updated_at before update on public.%I
                    for each row execute function public.set_updated_at()', t);
  end loop;
end $$;

create or replace function public.projects_set_published_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.status = 'published' and new.published_at is null then
    new.published_at := now();
  end if;
  return new;
end;
$$;

drop trigger if exists set_published_at on public.projects;
create trigger set_published_at before insert or update on public.projects
  for each row execute function public.projects_set_published_at();

create or replace function public.log_activity()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  rec   jsonb;
  label text;
begin
  if tg_op = 'DELETE' then
    rec := to_jsonb(old);
  else
    rec := to_jsonb(new);
  end if;

  -- Reordering alone is not an "edit" worth surfacing.
  if tg_op = 'UPDATE'
     and (to_jsonb(new) - 'sort_order' - 'updated_at') = (to_jsonb(old) - 'sort_order' - 'updated_at') then
    return null;
  end if;

  label := coalesce(rec->>'title', rec->>'name', rec->>'label', rec->>'full_name',
                    rec->>'site_name', rec->>'file_name', rec->>'institution',
                    rec->>'organization', rec->>'platform');

  insert into public.activity_log (entity, entity_id, action, title, actor)
  values (
    tg_table_name,
    rec->>'id',
    case tg_op when 'INSERT' then 'create' when 'UPDATE' then 'update' else 'delete' end,
    left(label, 200),
    (select auth.uid())
  );

  return null;
end;
$$;

do $$
declare t text;
begin
  foreach t in array array['profiles','site_settings','projects','achievements','skills',
                           'education','experience','media','social_links','stats']
  loop
    execute format('drop trigger if exists log_activity on public.%I', t);
    execute format('create trigger log_activity after insert or update or delete on public.%I
                    for each row execute function public.log_activity()', t);
  end loop;
end $$;

-- -----------------------------------------------------------------------------
-- Row Level Security
-- -----------------------------------------------------------------------------
alter table public.admin_users      enable row level security;
alter table public.profiles         enable row level security;
alter table public.site_settings    enable row level security;
alter table public.projects         enable row level security;
alter table public.achievements     enable row level security;
alter table public.skills           enable row level security;
alter table public.education        enable row level security;
alter table public.experience       enable row level security;
alter table public.media            enable row level security;
alter table public.social_links     enable row level security;
alter table public.stats            enable row level security;
alter table public.contact_messages enable row level security;
alter table public.activity_log     enable row level security;

-- admin_users: a signed-in user may only see whether they themselves are an admin.
drop policy if exists "admin_users: read own row" on public.admin_users;
create policy "admin_users: read own row" on public.admin_users
  for select to authenticated using (user_id = (select auth.uid()));

-- Singletons: readable by everyone, writable by admins only.
do $$
declare t text;
begin
  foreach t in array array['profiles','site_settings']
  loop
    execute format('drop policy if exists "%s: public read" on public.%I', t, t);
    execute format('create policy "%s: public read" on public.%I for select to anon, authenticated using (true)', t, t);
    execute format('drop policy if exists "%s: admin insert" on public.%I', t, t);
    execute format('create policy "%s: admin insert" on public.%I for insert to authenticated with check ((select public.is_admin()))', t, t);
    execute format('drop policy if exists "%s: admin update" on public.%I', t, t);
    execute format('create policy "%s: admin update" on public.%I for update to authenticated using ((select public.is_admin())) with check ((select public.is_admin()))', t, t);
  end loop;
end $$;

-- Publishable collections: visitors see published rows; admins see and manage everything.
do $$
declare t text;
begin
  foreach t in array array['projects','achievements','skills','education','experience','social_links','stats']
  loop
    execute format('drop policy if exists "%s: read published" on public.%I', t, t);
    execute format('create policy "%s: read published" on public.%I for select to anon, authenticated
                    using (status = ''published'' or (select public.is_admin()))', t, t);
    execute format('drop policy if exists "%s: admin insert" on public.%I', t, t);
    execute format('create policy "%s: admin insert" on public.%I for insert to authenticated with check ((select public.is_admin()))', t, t);
    execute format('drop policy if exists "%s: admin update" on public.%I', t, t);
    execute format('create policy "%s: admin update" on public.%I for update to authenticated using ((select public.is_admin())) with check ((select public.is_admin()))', t, t);
    execute format('drop policy if exists "%s: admin delete" on public.%I', t, t);
    execute format('create policy "%s: admin delete" on public.%I for delete to authenticated using ((select public.is_admin()))', t, t);
  end loop;
end $$;

-- Media: only published gallery images are publicly listed.
drop policy if exists "media: read public gallery" on public.media;
create policy "media: read public gallery" on public.media for select to anon, authenticated
  using ((in_gallery and status = 'published' and kind = 'image') or (select public.is_admin()));
drop policy if exists "media: admin insert" on public.media;
create policy "media: admin insert" on public.media for insert to authenticated with check ((select public.is_admin()));
drop policy if exists "media: admin update" on public.media;
create policy "media: admin update" on public.media for update to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
drop policy if exists "media: admin delete" on public.media;
create policy "media: admin delete" on public.media for delete to authenticated using ((select public.is_admin()));

-- Contact messages: no direct public access at all. Visitors submit through
-- public.submit_contact_message(); admins read, triage and delete.
drop policy if exists "contact: admin read" on public.contact_messages;
create policy "contact: admin read" on public.contact_messages for select to authenticated using ((select public.is_admin()));
drop policy if exists "contact: admin update" on public.contact_messages;
create policy "contact: admin update" on public.contact_messages for update to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
drop policy if exists "contact: admin delete" on public.contact_messages;
create policy "contact: admin delete" on public.contact_messages for delete to authenticated using ((select public.is_admin()));

drop policy if exists "activity: admin read" on public.activity_log;
create policy "activity: admin read" on public.activity_log for select to authenticated using ((select public.is_admin()));

-- Column-level hardening: visitors can never write to these tables directly.
revoke insert, update, delete on public.contact_messages from anon;
revoke insert, update, delete on public.activity_log from anon, authenticated;
revoke insert, update, delete on public.admin_users from anon, authenticated;

-- -----------------------------------------------------------------------------
-- Contact form submission (validated + rate limited inside the database)
-- -----------------------------------------------------------------------------
create or replace function public.submit_contact_message(
  p_name       text,
  p_email      text,
  p_subject    text,
  p_message    text,
  p_ip_hash    text default null,
  p_user_agent text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id     uuid;
  v_recent integer;
  v_name   text := btrim(coalesce(p_name, ''));
  v_email  text := lower(btrim(coalesce(p_email, '')));
  v_subj   text := btrim(coalesce(p_subject, ''));
  v_msg    text := btrim(coalesce(p_message, ''));
begin
  if char_length(v_name) not between 2 and 120 then
    raise exception 'invalid_name' using errcode = '22023';
  end if;
  if char_length(v_email) > 254 or v_email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'invalid_email' using errcode = '22023';
  end if;
  if char_length(v_subj) > 200 then
    raise exception 'invalid_subject' using errcode = '22023';
  end if;
  if char_length(v_msg) not between 10 and 5000 then
    raise exception 'invalid_message' using errcode = '22023';
  end if;

  -- Per-sender limit: 5 messages per hour from the same (hashed) IP.
  if p_ip_hash is not null then
    select count(*) into v_recent
    from public.contact_messages
    where ip_hash = p_ip_hash and created_at > now() - interval '1 hour';
    if v_recent >= 5 then
      raise exception 'rate_limited' using errcode = 'P0001';
    end if;
  end if;

  -- Global flood guard, in case the endpoint is hit directly with spoofed hashes.
  select count(*) into v_recent
  from public.contact_messages
  where created_at > now() - interval '10 minutes';
  if v_recent >= 30 then
    raise exception 'rate_limited' using errcode = 'P0001';
  end if;

  insert into public.contact_messages (name, email, subject, message, ip_hash, user_agent)
  values (v_name, v_email, v_subj, v_msg, left(p_ip_hash, 128), left(p_user_agent, 400))
  returning id into v_id;

  return v_id;
end;
$$;

revoke all on function public.submit_contact_message(text, text, text, text, text, text) from public;
grant execute on function public.submit_contact_message(text, text, text, text, text, text) to anon, authenticated;

-- -----------------------------------------------------------------------------
-- Storage: one public-read bucket. Uploads, replacement and deletion are
-- restricted to admins. MIME types and size are enforced by Storage itself,
-- so a modified client cannot bypass them. SVG is intentionally excluded
-- (it can carry scripts).
-- -----------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'media', 'media', true, 10485760,
  array['image/jpeg','image/png','image/webp','image/avif','image/gif',
        'image/x-icon','image/vnd.microsoft.icon','application/pdf']
)
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "media bucket: admin read" on storage.objects;
create policy "media bucket: admin read" on storage.objects for select to authenticated
  using (bucket_id = 'media' and (select public.is_admin()));
drop policy if exists "media bucket: admin insert" on storage.objects;
create policy "media bucket: admin insert" on storage.objects for insert to authenticated
  with check (bucket_id = 'media' and (select public.is_admin()));
drop policy if exists "media bucket: admin update" on storage.objects;
create policy "media bucket: admin update" on storage.objects for update to authenticated
  using (bucket_id = 'media' and (select public.is_admin()))
  with check (bucket_id = 'media' and (select public.is_admin()));
drop policy if exists "media bucket: admin delete" on storage.objects;
create policy "media bucket: admin delete" on storage.objects for delete to authenticated
  using (bucket_id = 'media' and (select public.is_admin()));


-- =============================================================================
-- v2: background music + single source of truth for the owner's name.
-- Safe to run more than once.
-- =============================================================================

-- Background music chosen in Admin → Settings → Sound.
alter table public.site_settings add column if not exists music_url text;
alter table public.site_settings add column if not exists music_title text not null default '';

-- Audio uploads in the media library.
alter table public.media drop constraint if exists media_kind_check;
alter table public.media add constraint media_kind_check check (kind in ('image', 'document', 'audio'));

update storage.buckets
set file_size_limit = 15728640,
    allowed_mime_types = array[
      'image/jpeg','image/png','image/webp','image/avif','image/gif',
      'image/x-icon','image/vnd.microsoft.icon','application/pdf',
      'audio/mpeg','audio/mp4','audio/x-m4a','audio/ogg','audio/wav','audio/webm','audio/aac'
    ]
where id = 'media';

-- The name now comes only from the profile. Clear the seeded copies of the old
-- default name so the site falls back to the profile name everywhere.
update public.site_settings set hero_title = ''        where hero_title = 'Shahruz Ziyodullayev';
update public.site_settings set site_name = coalesce((select full_name from public.profiles where id = 1), site_name)
  where site_name = 'Shahruz Ziyodullayev';
update public.site_settings set seo_title = ''         where seo_title = 'Shahruz Ziyodullayev — Portfolio';
update public.site_settings set seo_description = ''   where seo_description = 'Shahruz Ziyodullayevning shaxsiy portfoliosi: loyihalar, yutuqlar va tajriba.';
update public.site_settings set footer_text = ''       where footer_text = '© Shahruz Ziyodullayev. Barcha huquqlar himoyalangan.';
update public.profiles      set avatar_alt = ''        where avatar_alt = 'Shahruz Ziyodullayev portreti';

-- New colourful default accent (only if still on the original default).
update public.site_settings set accent_color = '#8b5cf6' where accent_color = '#10b981';
alter table public.site_settings alter column accent_color set default '#8b5cf6';


-- =============================================================================
-- v3: editorial monochrome design with a muted bronze accent.
-- Moves the accent to bronze only if it is still one of the earlier defaults.
-- Safe to run more than once.
-- =============================================================================
update public.site_settings set accent_color = '#c4a574' where accent_color in ('#8b5cf6', '#10b981');
alter table public.site_settings alter column accent_color set default '#c4a574';


-- =============================================================================
-- v4: editable home-page ticker and free-text experience periods.
-- Safe to run more than once.
-- =============================================================================

-- Words in the thin ticker under the hero (Admin → Settings → Hero).
alter table public.site_settings add column if not exists ticker_items text[] not null default '{}';

-- Optional display text for an experience period ("2026", "Summer 2025"),
-- used instead of the formatted start/end dates when set.
alter table public.experience add column if not exists period_label text not null default ''
  check (char_length(period_label) <= 60);


-- v5: the brief's bronze (#c5a059) as the default accent. Safe to run more than once.
update public.site_settings set accent_color = '#c5a059' where accent_color = '#c4a574';
alter table public.site_settings alter column accent_color set default '#c5a059';


-- Menu items that pointed at home-page sections now open their own pages.
update public.site_settings
set nav_items = (
  select coalesce(jsonb_agg(
    case item->>'href'
      when '/#highlights' then jsonb_set(item, '{href}', '"/highlights"')
      when '/#contact'    then jsonb_set(item, '{href}', '"/contact"')
      when '/#projects'   then jsonb_set(item, '{href}', '"/projects"')
      when '/#skills'     then jsonb_set(item, '{href}', '"/skills"')
      when '/#experience' then jsonb_set(item, '{href}', '"/experience"')
      else item
    end
    order by ord
  ), '[]'::jsonb)
  from jsonb_array_elements(nav_items) with ordinality as t(item, ord)
)
where id = 1;


-- Per-language copies of CMS text: { "uz": { "summary": "…" }, "ru": { … } }.
-- The regular columns keep the default (English) text; the site shows a
-- translated value instead when the visitor picked that language.

alter table public.site_settings add column if not exists translations jsonb not null default '{}'::jsonb;
alter table public.site_settings drop constraint if exists site_settings_translations_chk;
alter table public.site_settings add constraint site_settings_translations_chk
  check (jsonb_typeof(translations) = 'object' and pg_column_size(translations) < 200000);

alter table public.profiles add column if not exists translations jsonb not null default '{}'::jsonb;
alter table public.profiles drop constraint if exists profiles_translations_chk;
alter table public.profiles add constraint profiles_translations_chk
  check (jsonb_typeof(translations) = 'object' and pg_column_size(translations) < 200000);

alter table public.projects add column if not exists translations jsonb not null default '{}'::jsonb;
alter table public.projects drop constraint if exists projects_translations_chk;
alter table public.projects add constraint projects_translations_chk
  check (jsonb_typeof(translations) = 'object' and pg_column_size(translations) < 200000);

alter table public.achievements add column if not exists translations jsonb not null default '{}'::jsonb;
